[
  {
    "hypothesis_id": 10,
    "feature": {
      "name": "any_comment_cites_specific_real_world_example",
      "dtype": "binary",
      "source_columns": [
        "OC_comments"
      ],
      "definition": "Counter-argument comments (OC_comments): 1 if any comment explicitly cites a specific real-world example in support of its argument, else 0",
      "kind": "prompt",
      "spec": "Read OC_comments (JSON list of comments by users other than the OP; order carries no meaning). Output 1 if at least one comment explicitly cites a specific real-world example (a particular identifiable real event, person, case, organization, place, study, product or concrete documented instance, not a purely hypothetical, generic or vague 'some people' reference) as support for its argument. Named examples in the construct are nonexhaustive; no external verification is required. Quotes of others do not count unless the commenter uses them as a specific example. Output 0 if the list is valid and no comment does so. Empty list gives 0; missing or malformed input gives null."
    }
  },
  {
    "hypothesis_id": 17,
    "feature": {
      "name": "any_comment_quantifies_systemic_third_party_harm",
      "dtype": "binary",
      "source_columns": [
        "OC_comments"
      ],
      "definition": "Counter-argument comments (OC_comments, not OP): 1 if any comment explicitly quantifies systemic material harms to third parties, else 0",
      "kind": "prompt",
      "spec": "Read the JSON list in OC_comments (comments by users other than the OP; list order carries no meaning). Return 1 if at least one comment explicitly quantifies (gives numbers, magnitudes, rates, counts, costs or comparable explicit measures) material harms (e.g. economic, health, physical, loss of life or livelihood) that a system, policy or institutional pattern causes to third parties (people other than the commenter and OP). Qualitative harm claims without any quantification do not count; merely asserting that the OP's claim is false does not count; quotations of others' text not adopted by the commenter do not count. Return 0 if the list is valid and nonempty and no comment qualifies. Return 0 for a valid empty list. Return null if OC_comments is missing or malformed. Output a single 0/1/null."
    }
  }
]

